scwin.cal_tmpIsuexerDd_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.validate.isValidDate( selfVar,'행사일자');scwin.setLastIsuexerDd();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf20300.cal_tmpIsuexerDd_onblur' }); }
