 * @description chk Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDate = function () { /* 등가 no-op — 날짜 형식은 inputCalendar·제출 검증 몫 */ };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name searchIsuInfoChgList
 * @description search Isu Info Chg List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchIsuInfoChgList = async function () {
    await scwin.tx_fn_searchIsuInfoChgList('/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList');
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(function(idx) {
            $(this).find("input[name*=isuexer_dd]").attr("name", "dtl_isuexer_dd");
            $(this).find("input[name*=exer_shrs]").attr("name", "dtl_exer_shrs");
            $(this).find("input[name*=stk_rel_corpbnd_exer_prc]").attr("name", "dtl_stk_rel_corpbnd_exer_prc");
            $(this).find("input[name*=exer_amt]").attr("name", "dtl_exer_amt");
    });
    await scwin.tx_fn_save('/amount/amount.do?method=saveExerciseRightStock');
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const _mktact_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    }
    if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
        await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_afchgIsuAmt').getValue()) === 0) {
        await $c.win.alert("변경후 상장금액값이 없습니다. \n입력하신 행사금액을 확인하십시오.");
        return false;
    }
    let returnYn = true;
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(async function(idx) {
            const rowCnt = idx + 1;
            if ($(this).find("input[name*=isuexer_dd]").val() === '') {
                returnYn = false;
                await $c.win.alert(rowCnt + "번째 행의 행사일자를 입력하십시오");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return false;
            } else {
                if ($(this).find("input[name*=exer_shrs]").val() === '' || parseInt($(this).find("input[name*=exer_shrs]").val()) < 0) {
                    returnYn = false;
                    await $c.win.alert(rowCnt + "번째 행의 행사주식수를 입력하십시오");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                } else {
                    if ($(this).find("input[name*=stk_rel_corpbnd_exer_prc]").val() === '') {
                        returnYn = false;
                        await $c.win.alert(rowCnt + "번째 행의 행사가격을 입력하십시오");
                        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                        return false;
                    } else {
                        if ($(this).find("input[name*=exer_amt]").val() === '') {
                            returnYn = false;
                            await $c.win.alert(rowCnt + "번째 행의 행사금액을 입력하십시오");
                            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                            return false;
                        }
                    }
                }
            }
    });
    if (!returnYn) {
        return false;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) === 0) {
        return false;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
};

/**
 * @method
 * @name addRowExer
 * @description add Row Exer 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRowExer = function () {
    const newRow = $("#tmptable > tbody > tr:last").clone();
    newRow.insertAfter($("#exerciseRightDetl > tbody > tr:last"));
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(function(idx) {
            $(this).find("input[name*=isuexer_dd]").attr("name", "isuexer_dd" + idx);
            $(this).find("input[name*=isuexer_dd]").attr("id", "isuexer_dd" + idx);
            $(this).find("input[name*=isuexer_dd]").attr("onfocus", "cal_offMask('document.SendForm.isuexer_dd" + idx + ");");
            $(this).find("input[name*=isuexer_dd]").attr("onkeyup", "chkDate('document.SendForm.isuexer_dd" + idx + ");");
            $("#isuexer_dd" + idx).datepicker(myDateOpts);
            $(this).find("input[name*=exer_shrs]").attr("name", "exer_shrs" + idx);
            $(this).find("input[name*=stk_rel_corpbnd_exer_prc]").attr("name", "stk_rel_corpbnd_exer_prc" + idx);
            $(this).find("span[id*=stk_rel_corpbnd_exer_prc_kor]").attr("id", "stk_rel_corpbnd_exer_prc_kor" + idx);
            $(this).find("input[name*=exer_amt]").attr("name", "exer_amt" + idx);
            $(this).find("span[id*=exer_amt_kor]").attr("id", "exer_amt_kor" + idx);
    });
};

/**
 * @method
 * @name delRowExer
 * @description del Row Exer 처리
 * @returns {void}
 * @hidden N
 */
scwin.delRowExer = function () {
    const rows = jQuery("#exerciseRightDetl > tbody > tr");
    const rowIdx = rows.length;
    if (rowIdx > 1) {
        $("#exerciseRightDetl > tbody > tr:last").remove();
    }
};

/**
 * @method
 * @name setLastIsuexerDd
 * @description set Last Isuexer Dd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setLastIsuexerDd = function () {
    let last_isuexer_dd = "";
    let tmp_isuexer_dd = "";
    let rowIdx = "";
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(function(idx) {
            tmp_isuexer_dd = $(this).find("input[name*=isuexer_dd]").val();
            if (tmp_isuexer_dd > last_isuexer_dd) {
                last_isuexer_dd = tmp_isuexer_dd;
                rowIdx = idx;
            }
    });
    if (last_isuexer_dd == null || last_isuexer_dd === "") {
        return false;
    }
    $c.util.getComponent("ipt_lastIsuexerDd").setValue(last_isuexer_dd);
    return rowIdx;
};

/**
 * @method
 * @name setTotExershrs
 * @description set Tot Exershrs 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTotExershrs = function () {
    let tot_exer_shrs = 0;
    let tmp_exer_shrs = 0;
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(function(idx) {
            tmp_exer_shrs = $(this).find("input[name*=exer_shrs]").val();
            tmp_exer_shrs = tmp_exer_shrs.replace(/\,/g, '');
            if (tmp_exer_shrs == null || tmp_exer_shrs === "") {
                tmp_exer_shrs = 0;
            }
            tot_exer_shrs += parseInt(tmp_exer_shrs);
    });
    if (tot_exer_shrs == null || tot_exer_shrs === "") {
        tot_exer_shrs = "";
    } else {
        if (parseInt(tot_exer_shrs) < 0) {
            tot_exer_shrs = "";
        }
    }
    $c.util.getComponent("ipt_totExerShrs").setValue($c.num.formatMoney(tot_exer_shrs + ''));
    scwin.setExerAmt();
};

/**
 * @method
 * @name setStkRelCorpbndExerPrc
 * @description set Stk Rel Corpbnd Exer Prc 처리
 * @returns {void}
 * @hidden N
 */
scwin.setStkRelCorpbndExerPrc = function () {
    const rowIdx = scwin.setLastIsuexerDd();
    if (rowIdx < 0) {
        return;
    }
    const last_stk_rel_corpbnd_exer_prc = $("#exerciseRightDetl > tbody").find("tr:eq(" + rowIdx + ")").find("input[name*=stk_rel_corpbnd_exer_prc]").val();
    if (parseInt(last_stk_rel_corpbnd_exer_prc) >= 0) {
        $c.util.getComponent("ipt_lastStkRelCorpbndExerPrc").setValue(last_stk_rel_corpbnd_exer_prc);
    }
    scwin.setExerAmt();
};

/**
 * @method
 * @name setExerAmt
 * @description set Exer Amt 처리
 * @returns {void}
 * @hidden N
 */
scwin.setExerAmt = function () {
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(function(idx) {
            let tmp_exer_shrs = $(this).find("input[name*=exer_shrs]").val();
            tmp_exer_shrs = tmp_exer_shrs.replace(/\,/g, '');
            if (tmp_exer_shrs == null || tmp_exer_shrs === "") {
                tmp_exer_shrs = 0;
            }
            let tmp_stk_rel_corpbnd_exer_prc = $(this).find("input[name*=stk_rel_corpbnd_exer_prc]").val();
            tmp_stk_rel_corpbnd_exer_prc = tmp_stk_rel_corpbnd_exer_prc.replace(/\,/g, '');
            if (tmp_stk_rel_corpbnd_exer_prc == null || tmp_stk_rel_corpbnd_exer_prc === "") {
                tmp_stk_rel_corpbnd_exer_prc = 0;
            }
            let tmp_exer_amt = parseInt(tmp_exer_shrs) * parseInt(tmp_stk_rel_corpbnd_exer_prc);
            tmp_exer_amt = $c.num.formatMoney(tmp_exer_amt + '');
            $(this).find("input[name*=exer_amt]").val(tmp_exer_amt);
    });
    scwin.setTotExerAmt();
};

/**
 * @method
 * @name setTotExerAmt
 * @description set Tot Exer Amt 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTotExerAmt = function () {
    let tmp_exer_amt = 0;
    let tot_exer_amt = 0;
    /* 수동 전환 필요: 행 순회(id 선택자 #exerciseRightDetl) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#exerciseRightDetl > tbody > tr").each(function(idx) {
            tmp_exer_amt = $(this).find("input[name*=exer_amt]").val();
            tmp_exer_amt = tmp_exer_amt.replace(/\,/g, '');
            tot_exer_amt += parseInt(tmp_exer_amt);
    });
    if (tot_exer_amt == null || tot_exer_amt === "" || tot_exer_amt === 0) {
        return false;
    }
    let bfchgListAmt = $c.util.getComponent('ipt_bfchgListAmt').getValue();
    bfchgListAmt = bfchgListAmt.replace(/\,/g, '');
    bfchgListAmt = parseInt(bfchgListAmt);
    if (parseInt(tot_exer_amt) >= 0) {
        const afchg_isu_amt = bfchgListAmt - tot_exer_amt;
        $c.util.getComponent("ipt_totExerAmt").setValue($c.num.formatMoney(tot_exer_amt + ''));
        if (parseInt(afchg_isu_amt) >= 0) {
            $c.util.getComponent("ipt_afchgIsuAmt").setValue($c.num.formatMoney(afchg_isu_amt + ''));
        }
    }
};

